	// HYPOTHESIS-1: Removing all refuted complexity (prefix-load interaction, aggressive quadratic) and returning to proven minimal approach recovers best performance
	// MECHANISM-1: Prefix-load interaction was refuted 3x; aggressive quadratic penalties cause oscillation; the proven 96-token threshold + standard penalties work best
	// EXPECT-1: avg_e2e_ms < 2595
	// HYPOTHESIS-2: Small load-proportional reduction to prefix weight (not score penalty) for overloaded instances provides gentler anti-hotspot protection
	// MECHANISM-2: Instead of penalizing prefix scores directly (which causes oscillation), reduce w0 slightly when routing to heavily loaded instances, preserving cache affinity gradient
	// EXPECT-2: load_spikes_e2e_ms < 3350
	inputLen := len(req.InputTokens)
	w0 := ws.weights[0]
	w1 := ws.weights[1]
	if len(ws.weights) >= 2 {
		if inputLen < 96 {
			w0, w1 = 0.03, 0.97
		} else if inputLen < 256 {
			w0, w1 = 0.25, 0.75
